query:
NODE VALUE incoming_total SumAgg<INT64> = 0
TABLE incoming_rows {id STRING, total INT64}

MATCH (source:player)-[edge:follow]->(target:player)
PER PATH {
  SET target.@incoming_total += coalesce(edge.degree, 0)
}

MATCH (p:player)
PER NODE (p) {
  EXPORT p.id AS id, p.@incoming_total AS total INTO incoming_rows
}

FOR row IN incoming_rows
RETURN row.id AS id, row.total AS total
